import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';
import { readFileSync } from 'fs';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: { rejectUnauthorized: false }
});

// Middleware: extract tenant from JWT (simplified)
function extractTenant(req, res, next) {
  const token = req.headers['x-auth-token'];
  if (!token) return res.status(401).json({ error: 'unauthorized' });
  try {
    const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64').toString());
    req.tenantId = payload.tenant_id;
    req.userId = payload.sub;
    next();
  } catch (e) {
    return res.status(401).json({ error: 'invalid token' });
  }
}

// Template rendering endpoint - fetches user-defined report templates
app.post('/api/reports/generate', extractTenant, async (req, res) => {
  const { template_name, filters } = req.body;

  if (!template_name || typeof template_name !== 'string') {
    return res.status(400).json({ error: 'template_name required' });
  }

  // Validate template_name format (alphanumeric + underscore + hyphen)
  if (!/^[a-zA-Z0-9_-]+$/.test(template_name)) {
    return res.status(400).json({ error: 'invalid template name format' });
  }

  try {
    // Fetch template definition
    const templateResult = await pool.query(
      'SELECT * FROM report_templates WHERE name = $1 AND tenant_id = $2',
      [template_name, req.tenantId]
    );

    if (templateResult.rows.length === 0) {
      return res.status(404).json({ error: 'template not found' });
    }

    const template = templateResult.rows[0];

    // Build dynamic query from template + user filters
    let query = template.base_query; // e.g., "SELECT {columns} FROM {table} WHERE tenant_id = $1"

    // Apply user-provided filters to the WHERE clause
    const params = [req.tenantId];
    let paramIdx = 2;

    if (filters && typeof filters === 'object') {
      for (const [key, value] of Object.entries(filters)) {
        // Column name from filter key - validated against template's allowed_columns
        const allowedCols = template.allowed_columns; // JSON array from DB
        if (allowedCols.includes(key)) {
          query += ` AND ${key} = $${paramIdx}`;
          params.push(value);
          paramIdx++;
        }
      }
    }

    // User-controlled date range - VULNERABLE: date values interpolated directly
    if (req.body.date_from) {
      query += ` AND created_at >= '${req.body.date_from}'`;
    }
    if (req.body.date_to) {
      query += ` AND created_at <= '${req.body.date_to}'`;
    }

    // User-controlled LIMIT
    const limit = parseInt(req.body.limit) || 100;
    query += ` LIMIT ${limit}`;

    const result = await pool.query(query, params);

    return res.json({
      report: template_name,
      generated_at: new Date().toISOString(),
      row_count: result.rows.length,
      data: result.rows
    });
  } catch (err) {
    console.error('Report generation error:', err.message);
    return res.status(500).json({ error: 'internal error' });
  }
});

// Health check
app.get('/health', (req, res) => res.json({ status: 'ok' }));

app.listen(process.env.PORT || 3000);
